# Version 1.2: optional whole-screen transport, recording, and supported native background media.
for value in DOCS.values(): value['effective'] = 'Version 1.2 · Effective November 10, 2026'
def replace_everywhere(old, new):
    for value in DOCS.values():
        for section in value['sections']: section['body'] = section['body'].replace(old, new)
replace_everywhere('There is no Still account or developer-operated backend.', 'There is no Still account or preconfigured developer cloud service. Local video-link receiving needs no backend; optional whole-screen sharing uses the connection service you configure.')
replace_everywhere('Still does not operate an international telemetry transfer service of its own.', 'Still does not upload analytics. An optional screen-sharing connection or TURN service may operate internationally; choose its operator knowingly.')
replace_everywhere('and whether YouTube playback is allowed.', 'whether YouTube playback is allowed, background stream-audio preference, and the optional screen-sharing service address.')
replace_everywhere('and app-controlled data processing.', 'the Android Sender companion, optional connection-service source, and app-controlled data processing.')
replace_everywhere('Still is a foreground local-network link receiver and media player.', 'Still includes a foreground local-network link receiver, a media player and an optional WebRTC screen receiver for Android Sender and supported desktop browsers.')
replace_everywhere('and does not provide general-purpose screen mirroring.', 'and uses its own WebRTC screen-sharing mode rather than those protocols.')
replace_everywhere('It does not promise background hosting or whole-device screen mirroring.', 'It does not promise background server hosting or universal device compatibility. Whole-screen video can be received from the companion Android sender and supported desktop browsers; iPhone/iPad whole-screen sending is not included.')
replace_everywhere('Backgrounding stops receiving and pauses playback in this version.', 'Backgrounding stops local commands and WebRTC screen reception. Native direct-stream audio may continue if enabled, and native Picture in Picture can continue where iOS permits it. YouTube pauses. These exceptions do not keep the receiver server alive.')
replace_everywhere('backgrounding also pauses playback.', 'backgrounding also ends whole-screen reception and pauses YouTube. Native direct-stream audio or Picture in Picture may continue when enabled and supported.')
replace_everywhere('No subscription, account or feature-unlock purchase is included in this version.', 'No subscription, account or feature-unlock purchase is included in this version. Hosting and TURN bandwidth are separate operator costs, not an included free cloud service.')
replace_everywhere('The developer does not receive your playback activity through an app server.', 'The local-link mode does not send playback activity to an app server. Optional screen sharing necessarily sends negotiation and connection metadata to your selected operator; it is not an analytics upload.')
replace_everywhere('It does not turn an iPhone into a certified Google Cast or AirPlay receiver.', 'It does not turn an iPhone into a certified Google Cast or AirPlay receiver.')
replace_everywhere('Developer backend: none.', 'Preconfigured developer cloud service: none. Optional screen sharing: configured connection/TURN service.')
replace_everywhere('Your queue and pairing session stay in memory.', 'Your queue and pairing session stay in memory. Screen recordings you explicitly create persist locally until you delete or wipe them.')
replace_everywhere('Persistent watch history: none.', 'Automatic persistent watch history: none. Explicit screen recordings: local files until deleted.')
replace_everywhere('and resets app-owned data and preferences.', 'and resets app-owned data, saved screen recordings and preferences.')
replace_everywhere('It removes the app’s persistent preference domain, restores default playback settings', 'It waits for any active screen recording to finalize, deletes saved recordings, removes the app’s persistent preference domain, restores default playback settings')
replace_everywhere('On this device, Still retains appearance and playback preferences, screen name, privacy choices and onboarding status.', 'On this device, Still retains appearance and playback preferences, screen name, privacy choices, background stream-audio choice, configured screen-sharing server address and onboarding status. Explicit screen recordings persist as local MP4 files until deleted or wiped.')
replace_everywhere('No third-party runtime packages are bundled in this project.', 'The iOS screen receiver bundles WebRTC via stasel/WebRTC 157.0.0. The Android sender uses io.github.webrtc-sdk Android 150.7871.04 and OkHttp 4.12.0 with their transitive dependencies. The optional Node connection service uses ws 8.22.2. These components retain their own licenses; the project-specific NCL does not relicense them.')
replace_everywhere('No certified Google Cast receiver, YouTube Cast-menu discovery, AirPlay receiving, Miracast, whole-screen mirroring, DRM bypass, YouTube downloading, internet-wide remote hosting or IPv6-only local pairing.', 'No certified Google Cast receiver, YouTube Cast-menu discovery, AirPlay receiving, Miracast, iPhone/iPad whole-screen sending, DRM bypass, YouTube downloading, public exposure of the local HTTP command server or IPv6-only local-link pairing. Optional WebRTC screen-sharing invitations can work over the internet with deployed HTTPS and TURN services.')
replace_everywhere('The receiver stays open in the foreground.', 'Local-command and whole-screen receivers stay open in the foreground. Compatible native streams can use audio background mode or native Picture in Picture; this does not keep the receivers alive.')
replace_everywhere('iOS manages picture-in-picture availability through its native player where supported; Still provides no promise of background receiver service.', 'Native Picture in Picture is available through supported stream-player controls, and background stream audio is optional. Still provides no background receiver service.')
replace_everywhere('Screen video only, saved locally and excluded from backup by Still.', 'Screen video only, saved locally and excluded from backup by Still.')
DOCS['privacy']['sections'].extend([
 {'heading':'10. Optional whole-screen connections', 'body':"""Screen-sharing mode uses the HTTPS connection service configured on the receiving device. The developer supplies service source code but no hosted endpoint is preconfigured. The service exchanges a temporary room identifier, a private receiver-owner credential, an invitation credential, recording permission, session descriptions and ICE candidates. Session descriptions and candidates can reveal network addresses and device/media capabilities to the operator and the other peer. TLS protects signaling in transit to the operator; it does not hide these fields from that operator.

The supplied service keeps room state in memory, limits a session to two hours, retains a disconnected receiver briefly for reconnection, and clears room state when it ends or the process restarts. It adds no analytics or access-log feature. Infrastructure, reverse proxies, hosting providers or a customized deployment may create their own operational records. There is no promise that another operator follows this configuration.

WebRTC encrypts screen video in transit. Media travels directly between peers when possible; a configured TURN service can carry the encrypted media when network paths require it. The TURN operator can observe endpoints, timing and traffic volume. STUN services process network-discovery requests. These services are not automatically chosen from public providers in the supplied configuration. You decide which operator to trust; the app cannot guarantee anonymity, perfect security or connectivity on every network.

The Android companion uses the Android system screen-capture consent flow and an ongoing media-projection foreground service with a stop action. Android 13+ may request notification permission for its stop notification; if declined, use the app or Android’s active-app controls to stop. Desktop sending uses the browser’s screen picker. The sender can continue sharing while using other apps where its OS permits, but lock, revocation, battery policy or network changes can stop capture. Camera, microphone and system-audio capture are not implemented in this version. iPhone/iPad whole-screen sending is not implemented. A selected screen can reveal notifications, passwords or private messages; inspect what you share."""},
 {'heading':'11. Explicit local screen recordings', 'body':"""The receiver offers recording only for the WebRTC screen feed and only when the supplied sender has opted in before joining. Recording is off by default. A visible recording notice is sent to the sender. This consent control governs the supplied apps; it cannot prevent screenshots, external cameras, modified clients or other recording tools. Obtain any additional permission required by applicable law and by people whose information appears on screen.

Recordings contain screen video only, without audio. They are encoded as local MP4 files, with a 30-minute per-recording limit, bounded frame processing and a low-storage stop. Resolution is capped at a 1280-pixel long edge and the recording frame cadence is capped at 24 fps. Frames may be dropped to keep the player responsive. Protected content may be absent or black. This is not a YouTube downloader, stream-ripping tool or DRM bypass.

Saved recordings persist in Still’s application-support recordings folder until you delete or wipe them. The app marks that folder as excluded from backup; operating-system behavior and copies you export remain outside its control. A recording may include sensitive visible information. It is not automatically uploaded or saved to Photos. Sharing/exporting uses the system share sheet only after your action and needs no photo-library permission. Local Wipe deletes saved recordings after stopping and finalizing an active recording. Wipe cannot recall exported copies, provider records or existing backups. An interrupted save can leave a partial file; app startup attempts to remove incomplete recordings, and wipe removes the recordings folder."""},
 {'heading':'12. Background behavior', 'body':"""On the receiving iPhone/iPad, local commands and WebRTC screen reception end when the app enters the background. Active screen recording stops and gets a bounded opportunity to finish saving. The audio background mode is used only for compatible native media playback, not silent audio or a background-server workaround. If you enable Background stream audio, native stream audio can continue under iOS rules. Native Picture in Picture can continue supported video playback after you start it through the player. YouTube is paused when the app backgrounds. iOS may interrupt, suspend or end any session; no setting guarantees indefinite operation."""}
])
DOCS['terms']['sections'].append({'heading':'11. Whole-screen sharing and recording', 'body':"""Optional screen sharing uses WebRTC with the configured connection service and, when necessary, a separately operated TURN relay. It supports the supplied Android sender and compatible desktop browsers, with screen video only. HTTPS hosting, relay bandwidth, sender consent and adequate connectivity are prerequisites. No hosted service, zero-latency transport, guaranteed reconnection or whole-screen compatibility with every device is included.

Only share screens you are authorized to share. The receiving app honors the sender’s opt-in before enabling its recording function. A sender can revoke sharing through its app or OS capture control. This does not prevent external capture or authorize recording of copyrighted or private material. Recordings are local files subject to deletion and export choices described in the Privacy Policy. You are responsible for obtaining any legally necessary consent. The developer does not promise forensic deletion or recovery of a failed recording.

The Android sender may use a visible, system-approved media-projection foreground service. The iOS receiver cannot continue as an arbitrary background server. Native media audio and Picture in Picture exceptions do not change that limitation. No user instruction or app setting overrides OS permissions, protected-content controls or network outages."""})
DOCS['dataSafety']['sections'].append({'heading':'7. Screen sharing, recordings and wipe', 'body':"""Whole-screen connections use the configured service and optional STUN/TURN operators, who process connection metadata. Invitations are private bearer credentials. Owner credentials are not included in the sender invitation. Explicitly ending a session requests room revocation; if a device loses connectivity before that request arrives, the supplied service expires disconnected room state after a short grace period and sessions after two hours. Previously delivered data cannot be recalled.

Wipe stops screen receiving and recording as well as the local link receiver. It waits for any active recording to finish, then attempts to remove the recordings directory. If removal fails, it reports that some data may remain. It cannot delete the operator’s independent logs, another device’s state, or exported recordings. Saved recordings are excluded from backup by the app but are still sensitive local files until removed. App-level reset is not physical flash overwrite."""})
DOCS['compatibility']['sections'].append({'heading':'Whole-screen video', 'body':'Android 10+ with the Still Sender companion and system capture consent; compatible desktop browsers using HTTPS getDisplayMedia. WebRTC video-only reception, adaptive quality profiles, bounded reconnect attempts and opt-in local video recording. Internet sharing needs a deployed connection service, valid HTTPS and usually TURN. Android and desktop capture may continue while other apps are used, under OS rules. Receiving on iPhone/iPad remains foreground only. No remote input/control of the source device, microphone, system audio, iPhone/iPad sending or guaranteed playback of protected content.'})
DOCS['licenses']['sections'].extend([
 {'heading':'WebRTC · BSD license', 'body':(ROOT/'Still/Resources/WebRTC-LICENSE.txt').read_text().strip()},
 {'heading':'WebRTC · additional patent grant', 'body':(ROOT/'Still/Resources/WebRTC-PATENTS.txt').read_text().strip()},
 {'heading':'Android companion · Apache 2.0 notices', 'body':'OkHttp is Copyright Square, Inc.; Okio is Copyright Square, Inc.; Kotlin standard library is Copyright JetBrains s.r.o. and contributors. These components are used by the Android sender under Apache License 2.0. The full license follows. Separately bundled upstream notices retain their effect.\n\n'+(ROOT/'Still/Resources/Apache-2.0.txt').read_text().strip()}
])
document('screenSharing', 'Whole-screen sharing', [
 ('1. One-time connection setup', 'The app distributor or your administrator deploys the included HTTPS connection service and a TURN relay, then configures the service address in Still → Settings → Screen sharing. No hosted service is preconfigured in this source project. If you run your own service, use the repository deployment guide and a domain with a valid TLS certificate. This setup is required before normal users can receive an invitation.'),
 ('2. Invite a screen', 'On the receiving iPhone/iPad, choose Receive a whole screen, then Create an invitation. Share or scan the invitation on the sending device. Keep the invitation private. It allows one sending device per session. Starting screen mode stops the local link receiver and its current video to keep the two modes clear.'),
 ('3. Share from Android or a computer', 'On Android, install the Still Sender companion, open the invitation from the browser’s Open Android sender button or paste the full link into the companion. Choose a quality profile and whether recording is allowed, then choose a screen in Android’s permission dialog. On a supported computer browser, open the invitation, choose a profile and press Choose a screen. Your browser shows its own screen picker. iPhone/iPad whole-screen sending is not supported in this release.'),
 ('4. Record only with permission', 'The sender must allow recording before joining; it is off by default. On the receiver, Record this screen stores video-only MP4 locally, without audio. The sender sees a recording notice. Stop & save finalizes it. Recordings are capped at 30 minutes and stop when storage is low. Find, preview, share or delete recordings in Settings → Recordings. Local Wipe deletes them. External screen capture cannot be prevented by this consent setting.'),
 ('5. Nearby, distant and interrupted connections', 'The same invitation flow works nearby or across networks when the configured services can establish a WebRTC path. Congested Wi-Fi, mobile networks, firewalls, VPNs and long distances affect quality and delay. Try Lighter connection if needed. Both clients make bounded reconnection attempts after interruptions. Restart the invitation if recovery fails. The supplied service limits sessions to two hours and briefly preserves room state after a receiver disconnect.'),
 ('6. Background and stop controls', 'The Android sender uses a visible foreground media-projection service, and desktop capture can continue while another app is used where the sender OS allows it. Android lock or OS policies can revoke capture. The iPhone/iPad receiver must remain open for whole-screen receiving and recording. Backgrounding it ends screen sharing and saves any active recording if the OS gives time. Separate direct-stream playback may use native Picture in Picture or optional background audio; neither keeps screen receiving alive.'),
 ('7. Privacy and source restrictions', 'Screen video only is sent in this release. No camera, microphone, system audio or remote control of the sender. Notifications and private text visible on the selected screen can be exposed. Protected video can appear black, and provider restrictions are not bypassed. Signaling/TURN operators process connection metadata; WebRTC encrypts media in transit. Read the full bundled Privacy Policy and trust the configured service operator.')
])
DOCS['screenSharing']['effective'] = 'Version 1.2 · Effective November 10, 2026'

(ROOT/'Still/Resources/documents.json').write_text(json.dumps(DOCS, ensure_ascii=False, indent=2)+'\n')
(ROOT/'android-sender/app/src/main/assets').mkdir(parents=True, exist_ok=True)
(ROOT/'android-sender/app/src/main/assets/documents.json').write_text(json.dumps(DOCS, ensure_ascii=False, indent=2)+'\n')
for key, doc in DOCS.items():
    body = '# '+doc['title']+'\n\n'+doc['effective']+'\n\n'+'\n\n'.join('## '+s['heading']+'\n\n'+s['body'] for s in doc['sections'])+'\n'
    (ROOT/'docs'/f'{key}.md').write_text(body)
# The repository license and the bundled license have one canonical body.
lic = DOCS['ncl']
(ROOT/'LICENSE').write_text(lic['title']+'\n\n'+'\n\n'.join(s['heading']+'\n\n'+s['body'] for s in lic['sections'])+'\n')
if __name__ == '__main__':
    for key, doc in DOCS.items(): print(key, sum(len(s['body'].split()) for s in doc['sections']), 'words')
